+test('peek 返回栈顶且不改 size',()=>{const s=new BoundedStack(2);s.push(1);s.push(2);assert.equal(s.peek(),2);assert.equal(s.size,2);assert.equal(s.peek(),2);assert.equal(s.pop(),2);});
+test('空栈 peek 返回 undefined',()=>{const s=new BoundedStack(2);assert.equal(s.peek(),undefined);s.push(9);assert.equal(s.pop(),9);assert.equal(s.peek(),undefined);});

